  // Retention
  "excludes.advisoryImmichDb": "Immich ukládá alba, tváře a data pořízení ke každé fotce do databáze PostgreSQL, která běží ve vlastním, odděleném kontejneru, takže tato záloha ji neobsahuje. Obnova odsud vrátí obrázky, ale bez toho všeho. BombVault dumpuje kontejner té databáze automaticky, jakmile se zálohuje, takže ověř, že je ve tvém plánu.",
  "excludes.advisoryNextcloudDb": "Nextcloud ukládá účty, sdílení a štítky do databáze, která obvykle běží v odděleném kontejneru, takže tato záloha ji neobsahuje. Soubory se vrátí, sdílení ne. BombVault dumpuje kontejner té databáze automaticky, jakmile se zálohuje, takže ověř, že je ve tvém plánu.",
