  "excludes.presetHint.previews": "Vygenerované náhledové obrázky. Aplikace je po obnovení vytvoří znovu, u velké knihovny to může trvat hodiny.",
  "excludes.presetHint.trickplay": "Obrázky pro časovou osu. Naplánovaná úloha je po obnovení vytvoří znovu.",
  "excludes.presetHint.metadata": "Plakáty a obrázky stažené aplikací. Obnovení metadat je stáhne znovu, ale jsou tu i obrázky, které jsi nahrál sám, a ty by se ztratily. Tato položka je na začátku vypnutá.",
