  "excludes.presetHint.models": "Modely strojového učení. Aplikace je stáhne znovu při spuštění.",
  "rcloneRemote.heading": "Přidat cíl SMB nebo WebDAV",
  "rcloneRemote.hint": "Zpřístupní sdílenou složku Windows nebo Samba nebo server WebDAV, jako je Nextcloud, a to bez připojování na hostiteli. restic nedoporučuje mít repozitář na připojené sdílené složce CIFS a tento způsob se připojení úplně vyhne. Heslo se předá rclone, který si ho uloží ve vlastním formátu, a nikdy se neuchovává v otevřené podobě. NFS se zde nenabízí, protože ho neumí ani restic, ani rclone: pro NFS připoj export v Unraidu a nastav na něj Zálohovací cestu.",
