  // Off-site (rclone)
  "rclone.title": "Off-site (rclone)",
  "rclone.hint": "Vlož konfiguraci rclone pro zálohování do cloudu (Backblaze B2, S3, Google Drive, …). Ukládá se zašifrovaně. SMB/NFS rclone nepotřebují: připoj sdílenou složku v Unraidu a nastav na ni Zálohovací cestu.",
