  "rclone.pathHint": "Poté nastav Zálohovací cestu na „rclone:<remote>:<bucket>/path“, aby se tato sekce posílala off-site.",
  "cloud.title": "Výchozí přihlašovací údaje",
  "cloud.hint": "Přihlašovací údaje, které BombVault používá všude, kde nejsou uvedeny jiné, například při obnově na nové instalaci. Tajné údaje se ukládají šifrovaně a už se nikdy nezobrazí.",
