  "signIns.note.created": "Jsou uložené jako {name}, což je výchozí.",
  "signIns.note.duplicates": "one={n} uložená položka měla stejné klíče jako jiná a byla s ní sloučena.|few={n} uložené položky měly stejné klíče jako jiná a byly s ní sloučeny.|many={n} uložené položky mělo stejné klíče jako jiná a bylo s ní sloučeno.|other={n} uložených položek mělo stejné klíče jako jiná a bylo s ní sloučeno.",
  "signIns.note.linked": "Vlastní složka sekce {list} leží v cíli a řídí se jeho přihlašovacími údaji a ochranou.",
  "signIns.makeDefault": "Nastavit jako výchozí",
  "signIns.test": "Otestovat",
  "signIns.testUnused": "Tyto přihlašovací údaje nepoužívá žádný cíl, takže není na čem je otestovat.",
  "signIns.windowHint": "Změna platí pro každý cíl, který tyto přihlašovací údaje používá. „Otestovat“ se ke každému z nich přihlásí se zadanými hodnotami, aniž by cokoli uložil.",
  "offsite.copies.title": "Kopie mimo lokalitu",
  "rclone.paste": "Vložit konfiguraci",
  "whatsNew.signInMakeDefault": "Hvězdička označuje výchozí přihlašovací údaje, které platí všude, kde žádné vybrané nejsou. „Nastavit jako výchozí“ ji předá jiným.",
  "whatsNew.signInEdit": "„Upravit“ otevře přihlašovací údaje v okně, kde je „Otestovat“ před uložením vyzkouší u každého cíle, který je používá.",
  "whatsNew.gotItCheck": "Každé tlačítko „Rozumím“ má značku zaškrtnutí.",
  "whatsNew.cardFoot": "Tlačítka celé karty, třeba „Přidat cíl“, jsou na konci pod jejím obsahem.",
  "whatsNew.memoryLimit": "S limitem paměti na zálohu se velká záloha zpomalí, místo aby jí došla paměť.",
  "whatsNew.replicaTakeOver": "Složku ZFS repliky, kterou tento BombVault naplnil před novým nastavením, lze převzít a další replika naváže na kopie v ní.",
  "whatsNew.startOver": "Vzdálené úložiště, jehož repozitář zmizel, nedostane samo od sebe nový prázdný. Jeho stránka to řekne a nabídne tam založit nový repozitář.",
  "whatsNew.keyInstall": "Při nastavení Storage Boxu nebo serveru SFTP tam lze uložit klíč SSH BombVaultu heslem účtu, které se použije jednou a nikde se neuloží. Pod tím je příkaz, jak to udělat ručně.",
  "whatsNew.instancesCardLogo": "Každá karta instance ukazuje logo na stejném místě a ve stejné velikosti, v úrovni názvu.",
  "whatsNew.instancesNetLogos": "Na obrázku skupiny ukazuje každý BombVault logo s malým odznakem, který odliší server od telefonu.",
  "whatsNew.instancesCardSize": "Všechny karty instancí jsou stejně široké a vysoké jako ta nejvyšší.",
  "whatsNew.instancesFullNames": "Karty instancí ukazují celý název. Odznaky se u dlouhého názvu přesunou pod něj a druh instance má vlastní řádek.",
  "whatsNew.instancesNetLabels": "Názvy na obrázku skupiny se zalomí na další řádky, místo aby se ořízly.",
  "whatsNew.instancesInactive": "Vypnuté servery a telefony se zavřenou aplikací si ponechají kartu jako Neaktivní s časem, kdy byly naposledy viděny, dokud je neodeberete.",
  "whatsNew.instancesChecking": "Hned po spuštění BombVaultu ukazuje karta Ověřuje se, dokud se její instance nevrátí, místo aby vypadala jako zmizelá.",
  "whatsNew.pairingInactive": "Stránka Párování uvádí vypnuté servery a telefony se zavřenou aplikací jako Neaktivní s časem, kdy byly naposledy viděny.",
  "whatsNew.settingsStorageFlow": "Stránka nastavení Cíle ukazuje také, která sekce se zálohuje do kterého cíle.",
  "whatsNew.addOwnRclone": "„Přidat cíl“ má dlaždici Rclone pro vlastní konfiguraci rclone, kam vložíš remoty z rclone.conf.",
  "whatsNew.cryptPicture": "Obrázek šifrování sleduje svůj přepínač: zapečetěné balíky v cíli, když jsou zálohy šifrované, a čitelné, když nejsou.",
  "whatsNew.providerLogos": "V „Přidat cíl“ ukazují Amazon S3, Synology C2, Shade, 1Fichier, QingStor, Sia, FileLu, Drime a rclone svá loga a každá dlaždice se pod ukazatelem rozsvítí v barvě své značky. premiumize.me už v seznamu není, protože zálohy neukládá.",
  "whatsNew.serverHostKey": "Test připojení u SFTP a Hetzner Storage Box ukazuje otisk klíče serveru a BombVault server odmítne, pokud později ukáže jiný klíč.",
  "whatsNew.serverSwitches": "Nastavení typu ano, nebo ne u serverů FTP, SFTP a SMB jsou teď přepínače a FTP se ptá na šifrování jako na jednu volbu.",
  "whatsNew.smbShare": "Server SMB, který nevypisuje své sdílené složky, lze otestovat se jménem jedné složky a uložit lze až po otevření sdílené složky.",
  "whatsNew.settingsStorageList": "Stránka nastavení Cíle ukazuje všechny cíle. Kliknutím jeden otevřeš.",
  "whatsNew.offsiteCopies": "Kopie mimo lokalitu každé sekce je jeden řádek na jedné kartě, s testem, replikací a nastavením přímo v řádku. Vše ostatní se otevře v okně.",
  "whatsNew.compressionRow": "Výběr komprese stojí vedle svého popisku a je jen tak široký jako jeho tři možnosti.",
  "whatsNew.localProtection": "Místní složka ukazuje kartu Ochrana proti smazání jen tehdy, když má ochranu, kterou můžeš vypnout.",
