  "runReason.containersNotBack": "některé kontejnery se znovu nespustily",
  "dbdump.toggle": "Výpis databáze před každou zálohou",
  "dbdump.toggleHint": "BombVault rozpoznal tento kontejner jako databázi {engine}. Před každou zálohou požádá běžící server o úplný SQL výpis a uloží ho jako samostatný bod obnovy přímo do úložiště záloh, aniž by na tvé disky zapsal soubor. Obnova používá zálohu souborů pořízenou po zastavení kontejneru; výpis je druhá kopie, kterou si můžeš stáhnout nebo naimportovat. Neúspěšný výpis nikdy nezpůsobí selhání zálohy, objeví se jako samostatný neúspěšný běh.",
  "dbdump.toggleHintLabel": "Štítek kontejneru bombvault.dbdump zapíná výpis pro tuto databázi {engine}. Před každou zálohou požádá BombVault běžící server o úplný SQL výpis a uloží ho jako samostatný bod obnovy. Neúspěšný výpis nikdy nezpůsobí selhání zálohy, objeví se jako samostatný neúspěšný běh.",
  "dbdump.toggleHintOnlyCopy": "Před každou zálohou požádá BombVault tento běžící server {engine} o úplný SQL výpis a uloží ho jako samostatný bod obnovy. U tohoto kontejneru je výpis jedinou konzistentní kopií databáze: jeho datová složka se buď kopíruje za běhu serveru, nebo není v žádné záloze. Nech výpis zapnutý. Neúspěšný výpis nikdy nezpůsobí selhání zálohy, objeví se jako samostatný neúspěšný běh.",
  "dbdump.toggleHintUnknown": "Před každou zálohou požádá BombVault tento běžící server {engine} o úplný SQL výpis a uloží ho jako samostatný bod obnovy. Kde tento kontejner drží svou datovou složku, se nepodařilo zjistit, takže není jasné, jestli záloha souborů obsahuje použitelnou kopii. Výpis je kopie, na kterou se můžeš spolehnout. Nech ho zapnutý. Neúspěšný výpis nikdy nezpůsobí selhání zálohy, objeví se jako samostatný neúspěšný běh.",
  "dbdump.lookalikeHint": "Tento kontejner vypadá jako databáze {engine}, ale BombVault jeho obraz s jistotou nezná. Zapni výpis, pokud to databáze je; když pak selže, obraz se nedrží obvyklých nastavení a můžeš ho zase vypnout.",
  "dbdump.engineLabel": "Typ databáze",
  "dbdump.labelOff": "Vypnuto štítkem kontejneru bombvault.dbdump=false.",
  "dbdump.globalOff": "Automatické výpisy databází jsou vypnuté pro všechny kontejnery v Nastavení, Obecné.",
  "dbdump.offConfirmLive": "Vypnout výpis pro tuto databázi? Její datová složka se kopíruje za běhu serveru, takže bez výpisu neexistuje žádná konzistentní kopie.",
  "dbdump.offConfirmNone": "Vypnout výpis pro tuto databázi? Její datová složka není v žádné záloze, takže bez výpisu se z ní neuchová nic.",
  "dbdump.offConfirmUnknown": "Vypnout výpis pro tuto databázi? BombVault nezjistil, kde je její datová složka, takže není jasné, jestli nějaká záloha obsahuje použitelnou kopii.",
  "dbdump.coverageStopped": "Datová složka: uložena při zastaveném kontejneru.",
  "dbdump.coverageLive": "Datová složka: kopírována za běhu serveru. Výpis je konzistentní kopie.",
  "dbdump.coverageNone": "Datová složka: v žádné záloze. Výpis je jediná kopie.",
  "dbdump.coverageUnknown": "Datová složka: nepodařilo se zjistit. Nech výpis zapnutý.",
  "dbdump.coverageHint": "Databáze zapisuje do svých souborů neustále. Kopie těchto souborů je spolehlivá jen tehdy, když je server během jejího pořízení zastavený, a přesně to BombVault dělá pro složky v záloze kontejneru. Složky projektu compose nebo sady složek se kopírují za běhu serveru a složky mimo appdata se nekopírují vůbec. V těchto případech je výpis to, z čeho bys obnovoval.",
  "dbdump.hookOverlap": "Příkaz před zálohou tohoto kontejneru už dělá výpis databáze. Vypni jedno z obojího, jinak se databáze vypíše dvakrát.",
