  "dbdump.updateWarn": "Tohle je databáze. Aktualizace obrazu ji může posunout na novou hlavní verzi, která odmítne starou datovou složku. Výpis pořízený těsně před aktualizací se pak dá naimportovat do nové verze z panelu Zálohy.",
  "dbdump.updateWarnSameMajor": "Tohle je databáze. Aktualizace obrazu ji může posunout na novou hlavní verzi. MySQL a MariaDB importují výpis jen do hlavní verze, ze které pochází, takže když nová verze starou datovou složku nepřijme, vrať obraz na předchozí verzi a naimportuj tam výpis pořízený těsně před aktualizací.",
  "dbdump.stackRestoreWarn": "one=Data {names} se kopírují za běhu stacku. Po obnově naimportuj jeho nejnovější výpis databáze, než aplikaci začneš používat.|few=Data {names} se kopírují za běhu stacku. Po obnově naimportuj jejich nejnovější výpis databáze, než aplikace začneš používat.|many=Data {names} se kopírují za běhu stacku. Po obnově naimportuj jejich nejnovější výpis databáze, než aplikace začneš používat.|other=Data {names} se kopírují za běhu stacku. Po obnově naimportuj jejich nejnovější výpis databáze, než aplikace začneš používat.",
  "dbdump.introNotice": "one=BombVault před každou zálohou vypisuje rozpoznané databáze jako samostatné body obnovy. Rozpoznána zde: {n} databáze, {name}. Můžeš to vypnout u jednotlivého kontejneru na jeho kartě nebo pro všechny kontejnery v Nastavení.|few=BombVault před každou zálohou vypisuje rozpoznané databáze jako samostatné body obnovy. Rozpoznány zde: {n} databáze, první je {name}. Můžeš to vypnout u jednotlivého kontejneru na jeho kartě nebo pro všechny kontejnery v Nastavení.|many=BombVault před každou zálohou vypisuje rozpoznané databáze jako samostatné body obnovy. Rozpoznáno zde: {n} databáze, první je {name}. Můžeš to vypnout u jednotlivého kontejneru na jeho kartě nebo pro všechny kontejnery v Nastavení.|other=BombVault před každou zálohou vypisuje rozpoznané databáze jako samostatné body obnovy. Rozpoznáno zde: {n} databází, první je {name}. Můžeš to vypnout u jednotlivého kontejneru na jeho kartě nebo pro všechny kontejnery v Nastavení.",
  "dbdump.fixAuth": "Zkontroluj proměnné s heslem na samotném kontejneru databáze (například POSTGRES_PASSWORD, MARIADB_ROOT_PASSWORD nebo MYSQL_ROOT_PASSWORD, případně jejich varianty _FILE). Výpis používá přesně je.",
  "dbdump.fixPrivileges": "Výpis se dokázal přihlásit jen jako uživatel aplikace, kterému chybí potřebné oprávnění. Dej kontejneru skutečné heslo roota místo náhodného.",
  "dbdump.fixUnreachable": "Databázový server neodpověděl na svém lokálním socketu. Podívej se do logu kontejneru, možná ještě startuje nebo spadl.",
  "dbdump.fixNotRunning": "Kontejner byl pozastavený nebo se restartoval, když běžela záloha. Pokud se restartuje pořád dokola, podívej se do jeho logu.",
  "dbdump.fixNoClient": "Obraz nemá nástroj pro výpis. Použij oficiální obraz nebo pro tento kontejner výpis vypni.",
  "dbdump.fixSecret": "Soubor s heslem uvedený v proměnné _FILE nemohl uživatel kontejneru přečíst. Zkontroluj cestu a její oprávnění.",
  "dbdump.fixNoCredentials": "Nastavení kontejneru neobsahuje ani heslo roota, ani uživatele s databází. Nastav MARIADB_ROOT_PASSWORD (nebo MYSQL_ROOT_PASSWORD), případně uživatele a databázi.",
  "dbdump.fixNeedsUpgrade": "Systémové tabulky databáze pocházejí ze starší verze. Přidej kontejneru proměnnou MARIADB_AUTO_UPGRADE s hodnotou 1 a restartuj ho, nebo jednou spusť mariadb-upgrade uvnitř kontejneru.",
  "dbdump.fixTimeout": "Výpis narazil na svůj časový limit. U velmi velké databáze přidej kontejneru BombVault proměnnou DB_DUMP_MAX_HOURS (Unraid: uprav kontejner, Add another Path, Port, Variable), například 12.",
  "dbdump.fixBackupCap": "Celá záloha dosáhla BACKUP_MAX_HOURS, zatímco výpis běžel. Zvyš BACKUP_MAX_HOURS na kontejneru BombVault.",
  "dbdump.fixStalled": "Výpis se přestal posouvat, obvykle protože aplikace držela zámek. Zkusí se znovu s další zálohou.",
  "dbdump.fixDumpData": "Nástroj pro výpis se zastavil se zobrazenou zprávou. Zkusí se znovu s další zálohou; pokud bude selhávat dál, zpráva pojmenuje příčinu.",
  "dbdump.fixDocker": "Docker příkaz výpisu nespustil. Obvykle byl kontejner zastaven, pozastaven nebo znovu vytvořen, zatímco záloha startovala. Zkusí se znovu s další zálohou; pokud se to opakuje, zkontroluj službu Docker a přístup BombVaultu k ní.",
  "dbdump.fixRepository": "Repozitář záloh výpis nepřijal, nebo uložil méně bajtů, než kolik bylo vypsáno. Zkontroluj repozitář v Nastavení, Cíle; výpis se zkusí znovu s další zálohou.",
  "dbdump.fixLeftover": "Poškozený výpis se nepodařilo odstranit z úložiště. Smaž ho ze seznamu výpisů v panelu Zálohy.",
  "dbdump.fixHelper": "Pomocník výpisu BombVaultu skončil bez výsledku. Pokud se to opakuje, založ issue a přilož diagnostický balíček.",
  "dbdump.listTitle": "Výpisy databáze",
  "dbdump.listHint": "Každý výpis je úplný SQL export pořízený z běžící databáze těsně před jejím zálohováním. BombVault výpis nikdy sám nenahraje zpět: obnovení kontejneru obnoví jeho soubory, a pokud byly uloženy při zastaveném kontejneru, jsou novější kopií. Výpis použij, když ty soubory nestačí: byly kopírovány za běhu serveru nebo vůbec, databáze přešla na novou hlavní verzi nebo je datová složka poškozená. Import vloží výpis do čerstvě spuštěné prázdné databáze a starou datovou složku nechá vedle ní. Úplný soubor .sql končí komentářovým řádkem \"complete\".",
