  "dbdump.importRefused.noDataMount": "BombVault na datovou složku tohoto kontejneru nedosáhne a nemůže ji bezpečně odsunout. Importuj výpis ručně, jak to popisuje havarijní balíček.",
  "dbdump.importRefused.version": "Server běží ve verzi {server}, výpis pochází z {dump}. Pro tento import použij image s verzí {dump} nebo novější.",
  "dbdump.importRefused.versionSameMajor": "Server běží ve verzi {server}, výpis pochází z {dump}. MySQL a MariaDB importují výpis jen do hlavní verze, ze které pochází, proto pro tento import použij image s verzí {dump}.",
  "dbdump.importRefused.damaged": "Tento výpis je poškozený a nelze ho importovat.",
