  "recovery.abTitle": "Import z pluginu Appdata.Backup",
  "recovery.abIntro": "Z archivů, které zapsal plugin Appdata.Backup, udělá body obnovy odpovídajících kontejnerů, každý s datem, kdy ho plugin vytvořil. Archivy se jen čtou, nikdy se nemění ani nemažou. Každý se rozbalí vedle repozitáře, zazálohuje a rozbalená kopie se zase smaže, takže tam musí být místo pro největší archiv.",
