  "recovery.foreignLocation": "Adresa repozitáře",
  "recovery.foreignLocationHint": "Složka pod připojením hosta. Připoj na tomto hostiteli sdílení se zálohami druhého serveru a odkaž sem na něj. Repozitář musí být připojen lokálně (URL vzdálených repozitářů se zde nepřijímají).",
