  "mcp.statusNoneWorks": "Vypnuto: žádný klíč nefunguje",
  "mcp.noPasswordWarning": "Není nastavené přihlašovací heslo, takže je toto webové rozhraní otevřené všem ve tvé síti a kdo ho otevře, může také vytvořit klíč.",
  "mcp.setPassword": "Nastavit přihlašovací heslo",
  "mcp.needsPasswordForHost": "Tato stránka byla otevřena jako {host}. Bez přihlašovacího hesla lze klíče vytvářet a nahrazovat jen z IP adresy nebo z místního jména jako tower či tower.local, aby žádná stránka z internetu klíč vytvořit nemohla. Přihlašovací heslo toto omezení pro tuto adresu zruší. BombVault můžeš otevřít i přes jeho místní adresu.",
  "mcp.restoreRevokedNotice": "Obnovení konfigurace zneplatnilo všechny klíče MCP. Vytvoř pro své asistenty nové klíče.",
  "mcp.appKeyChanged": "APP_KEY se od vytvoření těchto klíčů změnil, takže už nefungují. Nahraď každý klíč a uprav své asistenty.",
  "mcp.keyUnusable": "Po změně APP_KEY už neplatí",
  "mcp.loadFailed": "Klíče MCP se nepodařilo načíst",
  "mcp.endpointLabel": "Koncový bod",
  "mcp.endpointHint": "Adresa, ke které se tvůj asistent připojuje. Mluví Streamable HTTP a očekává klíč v hlavičce Authorization nebo X-API-Key, případně přístupový token, jakmile se asistent přihlásí přes OAuth.",
  "mcp.newKey": "Nový klíč",
  "mcp.labelLabel": "Název klíče",
  "mcp.labelPlaceholder": "Claude Code na notebooku",
  "mcp.allowStart": "Povolit spouštění záloh",
  "mcp.allowStartHint": "Se zapnutou volbou může asistent zálohovat jednu položku, celou sekci nebo úplnou zálohu a rušit zálohy, které sám spustil: nejvýše {n} za hodinu, s odstupem {minutes} minut u téže položky a {perDay} na položku za den. Záloha zastaví běžící kontejnery, dokud neskončí. Bez ní může klíč jen číst.",
  "mcp.createKey": "Vytvořit klíč",
  "mcp.created": "Klíč vytvořen",
  "mcp.labelInvalid": "Dej klíči název o délce nejvýše 64 znaků.",
  "mcp.labelTaken": "Aktivní klíč už se tak jmenuje.",
  "mcp.limitReached": "one=Existuje už {n} aktivní klíč. Zneplatni ho, než vytvoříš další.|few=Existují už {n} aktivní klíče. Jeden zneplatni, než vytvoříš další.|many=Existuje už {n} aktivního klíče. Jeden zneplatni, než vytvoříš další.|other=Existuje už {n} aktivních klíčů. Jeden zneplatni, než vytvoříš další.",
  "mcp.newKeyTitle": "Tvůj nový klíč",
  "mcp.showOnce": "Zkopíruj si ho teď. BombVault si nechává jen jeho otisk a znovu ho ukázat nedokáže.",
  "mcp.copyKey": "Kopírovat klíč",
  "mcp.dismissKey": "Zkopíroval jsem si ho",
  "mcp.snippetsLabel": "Připojit klienta",
  "mcp.chooseClient": "Vybrat klienta",
  "mcp.search": "Hledat klienty",
  "mcp.noMatch": "Žádný klient neodpovídá. Jakýkoli jiný klient se připojí přes „Jiný klient“.",
  "mcp.connectHint": "Vyber svého klienta a dostaneš nastavení udělané přímo pro něj: klíč s jeho jménem, konfiguraci ke zkopírování a krok s certifikátem, který potřebuje. Každý jiný klient se připojí přes Jiný klient. Co asistent čte, třeba názvy položek, historii a chybová hlášení, jde k poskytovateli AI za ním, poté co BombVault odstraní cesty hostitele, umístění repozitářů a přihlašovací údaje.",
  "mcp.groupLocal": "Na tomto počítači",
  "mcp.groupCloud": "V cloudu",
  "mcp.cloudWarningTitle": "BombVault musí být dostupný z internetu",
  "mcp.cloudWarning": "Tyto služby volají BombVault ze serverů svého poskytovatele, ne z tvého počítače. BombVault pak musí být dostupný z internetu s veřejně důvěryhodným certifikátem, například za reverzní proxy. Přihlášení na této proxy může chránit webové rozhraní, ale /mcp musí projít až k BombVaultu, který klíč kontroluje sám: tyto služby se k proxy přihlásit neumějí. Le Chat odmítá certifikáty podepsané sebou samým.",
  "mcp.otherClient": "Jiný klient",
  "mcp.kindTerminal": "Terminál",
  "mcp.kindEditor": "Editor",
  "mcp.kindDesktop": "Desktopová aplikace",
  "mcp.kindVsCode": "Rozšíření VS Code",
