  "anomaly.prunePaused": "Vyčištěno. Staré zálohy položek s otevřenou anomálií zůstaly zachovány: {names}",
  "anomaly.settings.title": "Anomálie",
  "anomaly.settings.hint": "Porovnává každou zálohu položky s její vlastní historií a hlásí, co k ní nesedí. Běží na pozadí po každé záloze a žádnou nezpomalí. Většina kontrol začíná po 10 zálohách položky; selhání, přepsání většiny dat a téměř prázdný zdroj se kontrolují od začátku. Volné místo se sleduje u místních repozitářů a u repozitářů rclone, které ho hlásí; na uživatelské sdílené složce Unraidu jde o volné místo celého pole.",
